// ATS URL rewriting: convert JS-rendered ATS URLs to API-friendly endpoints
// This runs before Fetch Job Page so the HTTP request gets scrapeable content.
const helpers = this.helpers;
const BH_FIELDS = 'id,title,publishedCategory(id,name),address(city,state,countryName),employmentType,dateLastPublished,publicDescription,isOpen,isPublic,isDeleted,publishedZip,salary,salaryUnit';
// Fallback Bullhorn config per host, used only if app.json cannot be read.
// To add a site: open {host}/wp-content/plugins/bullhorn-oscp/app.json and copy service.swimlane + service.corpToken.
const BH_FALLBACK = { 'example-staffing.com': { swimlane: '<SWIMLANE>', corpToken: '<CORP_TOKEN>' } };
// ── v6: KNOWN_SPA_HOSTS ──────────────────────────────────────
// Hostnames where the static HTML is a JS shell, must go through Jina/Decodo render.
// Add new hosts here as discovered. Match is case-insensitive endsWith on hostname.
const KNOWN_SPA_HOSTS = [
  'example-manufacturer.com',   // Phenom People style page that builds itself in the browser, no SSR JSON-LD
  // 'phenompeople.com',    // example of broader catch-all
];
function isKnownSpaHost(u) {
  try {
    var h = new URL(u).hostname.toLowerCase();
    return KNOWN_SPA_HOSTS.some(function(s){ return h === s || h.endsWith('.' + s); });
  } catch (e) { return false; }
}
// ─────────────────────────────────────────────────────────────

const bhConfigCache = {};
async function getBullhornConfig(bhBase, hostName) {
  if (bhConfigCache[hostName] !== undefined) return bhConfigCache[hostName];
  let conf = BH_FALLBACK[hostName] || null;
  try {
    const cfg = await helpers.httpRequest({ url: bhBase + '/app.json', json: true, timeout: 10000 });
    if (cfg && cfg.service && cfg.service.swimlane && cfg.service.corpToken) {
      conf = { swimlane: String(cfg.service.swimlane), corpToken: String(cfg.service.corpToken) };
    }
  } catch (e) { /* keep fallback */ }
  bhConfigCache[hostName] = conf;
  return conf;
}
// ── ADP_CX_HELPER_START (v29) ────────────────────────────────
// myjobs.adp.com job pages are an Angular page that builds itself in the browser with a catch-all route: sitemap.xml,
// robots.txt, /job-preview and a googlebot UA all return the SAME 2,394-byte shell.
// The public JSON API is the only readable source, and it wants orgoid as a HEADER
// (?orgoid= => HTTP 400 "Missing orgoid"), so the header rides on the item.
const adpCxOrgCache = {};
async function getAdpCxOrgoid(cid) {
  if (adpCxOrgCache[cid] !== undefined) return adpCxOrgCache[cid];
  let oid = null;
  try {
    let site = await helpers.httpRequest({
      url: 'https://myjobs.adp.com/public/staffing/v1/career-site/' + cid,
      method: 'GET', json: true, timeout: 20000,
      headers: { 'User-Agent': 'Mozilla/5.0', Accept: 'application/json' },
    });
    if (typeof site === 'string') site = JSON.parse(site);
    oid = (site && site.orgoid) || null;
  } catch (e) { /* leave null — falls through to the SPA URL and the render chain */ }
  adpCxOrgCache[cid] = oid;
  return oid;
}
// ── ADP_CX_HELPER_END ──

// ── APPLITRACK_HELPER_START (v52) ────────────────────────────
// The AppliTrack posting's own "Location:" field is a building/department name,
// so the district's street address comes from its careers-site footer instead.
const atAddrCache = {};
async function getAppliTrackAddress(tenant) {
  if (atAddrCache[tenant] !== undefined) return atAddrCache[tenant];
  var addr = '';
  try {
    var home = await helpers.httpRequest({
      url: 'https://www.applitrack.com/' + tenant + '/onlineapp/default.aspx',
      method: 'GET', timeout: 20000, headers: { 'User-Agent': 'Mozilla/5.0' },
    });
    var lines = String(home || '')
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|ul|ol|tr|h[1-6])>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;?/gi, ' ').replace(/&amp;/g, '&')
      .split('\n')
      .map(function (l) { return l.replace(/^[\s\r\u2022]+/, '').replace(/[\s\r]+$/, ''); })
      .filter(function (l) { return l; });
    var admin = -1;
    for (var i = 0; i < lines.length; i++) { if (/^Admin Login$/i.test(lines[i])) { admin = i; break; } }
    if (admin !== -1) {
      // The footer prints "<street>" and "<City, ST ZIP>" as separate list items,
      // but whether they land on one line or two depends on the district's markup,
      // so match a line ENDING in City, ST ZIP and keep whatever precedes it.
      for (var j = admin - 1; j >= 0 && j >= admin - 4; j--) {
        // greedy prefix on purpose: the city group must take the LEAST it can, or
        // "145 Spring Valley Road Paramus, NJ 07652" splits after the house number.
        var cs = lines[j].match(/^(.*)([A-Z][A-Za-z.'\-]+,\s*[A-Z]{2}\s*\d{5}(?:-\d{4})?)$/);
        if (!cs) continue;
        var street = cs[1].replace(/[,\s]+$/, '').trim();
        if (!street && j > 0 && /\d/.test(lines[j - 1]) && !/^Admin/i.test(lines[j - 1]) &&
            !/[A-Z]{2}\s*\d{5}/.test(lines[j - 1])) street = lines[j - 1];
        addr = (street ? street + ', ' : '') + cs[2];
        break;
      }
    }
  } catch (e) { /* leave blank — the LLM still gets the posting, just no street */ }
  atAddrCache[tenant] = addr;
  return addr;
}
// ── APPLITRACK_HELPER_END ──

async function rewriteAtsUrl(url) {
  if (!url) return { url, ats: null };

  // ── ADP_CX_REWRITE_START (v29) ──
  // myjobs.adp.com/{cid}/cx/job-details?reqId={id}, [^#]* spans the query string
  // because Sempra's links carry ?c=…&reqId=…, that is, reqId is not always first.
  var adpCxM = url.match(/myjobs\.adp\.com\/([^\/?#]+)\/cx\/[^#]*[?&]reqId=(\d+)/i);
  if (adpCxM && adpCxM[1].toLowerCase() !== 'public') {
    var adpCxOid = await getAdpCxOrgoid(adpCxM[1]);
    // Without an orgoid the API is unusable: leave the original URL so the
    // existing render chain still gets its try rather than fetching a 400.
    if (adpCxOid) {
      return { url: 'https://myjobs.adp.com/public/staffing/v1/job-requisitions/' + adpCxM[2],
               ats: 'adp_cx', orgoid: adpCxOid };
    }
  }
  // ── ADP_CX_REWRITE_END ──

  // ADP Workforce Now: public careercenter API (returns full job JSON incl. salary + locations)
  var adpM = url.match(/workforcenow\.adp\.com.*?[?&]cid=([^&#]+).*?[?&]jobId=([^&#]+)/);
  if (adpM) {
    var ccM = url.match(/[?&]ccId=([^&#]+)/);
    var ccId = ccM ? ccM[1] : '19000101_000001';
    var apiUrl = 'https://workforcenow.adp.com/mascsr/default/careercenter/public/events/staffing/v1/job-requisitions/'
      + adpM[2] + '?cid=' + adpM[1] + '&timeStamp=' + Date.now() + '&lang=en_US&ccId=' + ccId;
    return { url: apiUrl, ats: 'adp' };
  }

  // ── JOBVITE_NL0_START (v30) ──
  // A bare jobs.jobvite.com/{slug}/job/{id} 302s to the employer's own careers page
  // on any tenant with link-swap enabled (McCarthy). ?nl=0 keeps Jobvite serving the
  // server-rendered posting. Any pre-existing query string is dropped on purpose:
  // ?nl=1 and ?__jvst=… both trigger the swap (both measured returning the 119 KB
  // careers page), and Jobvite needs no other parameter to resolve a job id.
  var jvDirectM = url.match(/^https?:\/\/jobs\.jobvite\.com\/([^\/?#]+)\/job\/([A-Za-z0-9]+)/i);
  if (jvDirectM) {
    return { url: 'https://jobs.jobvite.com/' + jvDirectM[1] + '/job/' + jvDirectM[2] + '?nl=0', ats: 'jobvite' };
  }
  // ── JOBVITE_NL0_END ──

  // Jobvite iframe embed: company.com/path?jobviteiframe=job/JOB_ID
  // Redirect to jobs.jobvite.com/{slug}/job/{id}?nl=1 which renders server-side HTML
  var jvM = url.match(/[?&]jobviteiframe=job\/([A-Za-z0-9]+)/);
  if (jvM) {
    var jobId = jvM[1];
    var domM = url.match(/https?:\/\/(?:www\.)?([^./]+)\./);
    var slug = domM ? domM[1] : 'careers';
    // v30: nl=0, not nl=1: on a link-swap tenant nl=1 bounces to the company's
    // own careers page, which is a client-side widget with no posting in the HTML.
    return { url: 'https://jobs.jobvite.com/' + slug + '/job/' + jobId + '?nl=0', ats: 'jobvite' };
  }

  // Bullhorn OSCP: job identity lives only in the #/jobs/{id} hash fragment,
  // which HTTP never sends. Resolve the company's Bullhorn public REST endpoint
  // (swimlane + corpToken from the portal app.json) and query the job by id.
  var bhM = url.match(/^(https?:\/\/[^/]+)(\/.*?bullhorn-oscp)\/#\/jobs\/(\d+)/);
  if (bhM) {
    var bhBase = bhM[1] + bhM[2];
    var bhJobId = bhM[3];
    var hostName = bhM[1].replace(/^https?:\/\//, '');
    var conf = await getBullhornConfig(bhBase, hostName);
    if (conf) {
      var apiUrl = 'https://public-rest' + conf.swimlane + '.bullhornstaffing.com/rest-services/' +
        conf.corpToken + '/query/JobBoardPost?where=(id=' + bhJobId + ')&fields=' + BH_FIELDS + '&count=1';
      return { url: apiUrl, ats: 'bullhorn' };
    }
    // Config unknown: do not guess another company's token; let Jina try the rendered page.
    return { url: url, ats: null };
  }

  // Paycom: flag for better error message (no known API)
  if (url.includes('paycomonline.net/v4/ats')) {
    return { url, ats: 'paycom' };
  }

  // Radancy-hosted careers: flag for better error message
  if (url.includes('careers.example-aerospace.com')) {
    return { url, ats: 'textron' };
  }

  // TalentLink / TGS: UBS and other companies (for example jobs.example-financial.com/TGnewUI/)
  // No accessible API; keep URL unchanged but mark as talentlink so Clean HTML parses the Q&A JSON.
  if (url.includes('/TGnewUI/') || url.includes('TGWebAPI')) {
    return { url, ats: 'talentlink' };
  }


  // ── Dayforce HCM (Ceridian), v3 ─────────────────────────────
  // Patterns:
  //   jobs.dayforcehcm.com/en-US/{client}/CANDIDATEPORTAL/jobs/{id}              (standard)
  //   jobs.dayforcehcm.com/en-US/{client}/CANDIDATEPORTAL{customSuffix}/jobs/{id} (custom portal name, for example Balfour)
  //   jobs.dayforcehcm.com/en-US/{client}/{siteId}/jobs/{id}                     (legacy numeric site id, for example Xencor 112515)
  // We preserve the middle segment exactly: API path mirrors the public path.
  var dfM = url.match(/dayforcehcm\.com\/(en-US|[a-z]{2}-[A-Z]{2})\/([^\/]+)\/([^\/]+)\/jobs\/(\d+)/i);
  if (dfM) {
    return { url: 'https://jobs.dayforcehcm.com/' + dfM[1] + '/' + dfM[2] + '/' + dfM[3] + '/jobs/' + dfM[4], ats: 'dayforce' };
  }

  // ── Avature career portals (for example careers.example-realestate.com, careers.example-engineering.com) ──
  // Pattern: /en_US/careers/JobDetail/{slug}/{jobId}. Server-rendered (often with
  // JSON-LD JobPosting), fetch the page directly and let the HTML / JSON-LD parser
  // handle it. NOTE: some Avature sites sit behind an AWS bot blocker bot-
  // challenge; those fall through to the Jina renderer and may still need a manual
  // paste into Raw Job Text.
  var avatureM = url.match(/\/en_US\/careers\/JobDetail\/[^\/]+\/\d+/);
  if (avatureM) {
    return { url: url, ats: null };
  }

  // ── Phenom People: v2 (no rewrite) ──────────────────────────
  // Phenom sites SSR JobPosting JSON-LD for SEO. The /api/jobs/{id} endpoint
  // is unreliable across tenants (SAIC returns 404, others return non-standard shapes).
  // Strategy: fetch the public page directly, let JSON-LD extractor in Clean HTML do the work.
  // No rewrite, no special handler: falls through to the standard HTML pipeline.

  // ── Oracle Taleo Career Section ──────────────────────────────
  // Pattern: {tenant}.taleo.net/careersection/{section}/jobdetail.ftl?job={jobId}
  // Taleo HTML is a JS shell; content loads via AJAX. We don't rewrite the URL
  // (the public REST endpoint needs session cookies), but we tag the platform so
  // Decodo fetch waits longer and the HTML parser targets Taleo's DOM structure.
  var taleoM = url.match(/([a-z0-9-]+)\.taleo\.net\/careersection\/([^\/]+)\/jobdetail\.ftl\?job=([A-Za-z0-9]+)/i);
  if (taleoM) {
    return { url: url, ats: 'taleo' };
  }

  // ── Apploi ───────────────────────────────────────────────────
  // Apploi pages are JS-rendered SPAs; the job lives in a public JSON API.
  var appM = url.match(/apploi\.com\/view\/(\d+)/);
  if (appM) {
    return { url: 'https://api.apploi.com/v1/jobs/' + appM[1], ats: 'apploi' };
  }

  // ── NEW v3: ClearCompany ─────────────────────────────────────
  // Pattern: {company}.clearcompany.com/careers/jobs/{guid}
  // Pages are server-rendered with JSON-LD; fetch directly and fall through
  // to the HTML / JSON-LD parser (no JSON API rewrite needed).
  var ccM = url.match(/[a-z0-9-]+\.clearcompany\.com\/careers\/jobs\/[a-zA-Z0-9-]+/);
  if (ccM) {
    return { url, ats: 'clearcompany' };
  }

  // ── UltiPro / UKG Pro: v2 ───────────────────────────────────
  // Pattern: recruiting{N?}.ultipro.com/{COMPANY}/JobBoard/{boardId}/OpportunityDetail?opportunityId={guid}
  // N covers regional data centres: recruiting, recruiting1, recruiting2, recruiting3, recruiting4
  // We preserve the original subdomain in the API URL since each data centre is independent.
  var ukgM = url.match(/(recruiting\d*\.ultipro\.com)\/([^\/]+)\/JobBoard\/([a-f0-9-]+)\/OpportunityDetail\?opportunityId=([a-f0-9-]+)/i);
  if (ukgM) {
    return { url: 'https://' + ukgM[1] + '/' + ukgM[2] + '/JobBoard/' + ukgM[3] + '/JobDetails/Load?opportunityId=' + ukgM[4], ats: 'ukg' };
  }

  // ── ADP Workforce Now mascsr (multi-tenant) ──────────────────
  // Pattern: workforcenow.adp.com/mascsr/.../recruitment.html?cid={cid}&jobId={id}
  var adpMascsrM = url.match(/workforcenow\.adp\.com\/mascsr\/[^?]*?[?&]cid=([^&#]+).*?[?&]jobId=([^&#]+)/);
  if (adpMascsrM) {
    return { url: 'https://workforcenow.adp.com/mascsr/default/api/career/job?cid=' + adpMascsrM[1] + '&jobId=' + adpMascsrM[2], ats: 'adp_mascsr' };
  }

  // ── APPLITRACK_REWRITE_START (v52) ──
  // applitrack.com/{tenant}/onlineapp/default.aspx?AppliTrackJobId={id} is a shell
  // that document.write()s the posting in. view.asp?embed=1 is the server-rendered
  // equivalent (the site's own <noscript> link) and carries the whole posting.
  var atM = url.match(/applitrack\.com\/([^\/?#]+)\/onlineapp\/[^?#]*\?[^#]*AppliTrackJobId=(\d+)/i);
  if (atM) {
    var atTenant = atM[1], atJobId = atM[2];
    return {
      url: 'https://www.applitrack.com/' + atTenant + '/onlineapp/jobpostings/view.asp?embed=1&AppliTrackJobId=' + atJobId,
      ats: 'applitrack',
      applitrackJobId: atJobId,
      applitrackAddress: await getAppliTrackAddress(atTenant),
    };
  }
  // ── APPLITRACK_REWRITE_END ──

  // ── ORACLE_CE_REWRITE_START ──
  // Oracle Recruiting Cloud ("Oracle CE"):
  //   {host}/hcmUI/CandidateExperience/{lang}/sites/{site}/job/{id}
  // The public page is a JS shell that boots a Terms-and-Conditions gate and the
  // "Career Coach" chatbot, so a Jina/Decodo render scrapes the BOT, not the job
  // (2026-08-03: one board’s rows came back titled "Career Coach" with the T&C blurb as
  // the description). Every tenant exposes the same public REST resource on its own
  // host, and the trailing /job/{id} segment IS the requisition Id, numeric (505)
  // or alphanumeric (2600014G).
  // siteNumber is deliberately omitted: that board ignores the parameter, and guessing
  // CX_1 on a multi-site tenant would break a call that already works without it.
  var oraM = url.match(/^(https?:\/\/[^\/]+)\/hcmUI\/CandidateExperience\/.*?\/job\/([A-Za-z0-9_-]+)/i);
  if (oraM) {
    return { url: oraM[1] + '/hcmRestApi/resources/latest/recruitingCEJobRequisitionDetails?expand=all&finder=ById;Id=%22' + encodeURIComponent(oraM[2]) + '%22', ats: 'oracle_ce' };
  }
  // ── ORACLE_CE_REWRITE_END ──

  // ── BAMBOOHR_REWRITE_START (v75) ──
  // {tenant}.bamboohr.com/careers/{id} is a JS SHELL, measured 2026-09-01 on
  // one board’s listing page: 98 KB, no JSON-LD, no __NEXT_DATA__, and the word "hybrid" appears
  // ZERO times although the posting says "This position is hybrid". So the row could
  // only ever be read through a Jina/Decodo render.
  // /careers/{id}/detail is the same posting as public JSON with structured city /
  // state / postalCode / country, employmentStatusLabel and compensation.
  // Tenant-generic, keyed on the host.
  var bhM = url.match(/^https?:\/\/([a-z0-9-]+)\.bamboohr\.com\/careers\/(\d+)(?:[\/?#]|$)/i);
  if (bhM && !/\/careers\/\d+\/detail/i.test(url)) {
    return {
      url: 'https://' + bhM[1] + '.bamboohr.com/careers/' + bhM[2] + '/detail',
      ats: 'bamboohr',
      bamboohrJobId: bhM[2]
    };
  }
  // ── BAMBOOHR_REWRITE_END ──

  return { url, ats: null };
}

const out = [];
for (const item of items) {
  const originalUrl = item.json['Job Link'];
  const rewrite = await rewriteAtsUrl(originalUrl);
  var _forceRenderHost = isKnownSpaHost(originalUrl);
  out.push({
    json: {
      record_id: item.json.id,
      force_render: _forceRenderHost,
      job_link: rewrite.url,
      original_job_link: rewrite.ats ? originalUrl : null,
      ats_platform: rewrite.ats,
      adp_orgoid: rewrite.orgoid || null,
      applitrack_job_id: rewrite.applitrackJobId || null,
      applitrack_address: rewrite.applitrackAddress || null,
      bamboohr_job_id: rewrite.bamboohrJobId || null,
      company: item.json['Company'] || null,
      raw_job_text: item.json['Raw Job Text'] || null,
      current_status: item.json['Status'] || '',
      current_address: item.json['Address'] || '',
    }
  });
}
return out;

const prev = $('Loop (rate limit)').item.json;
const response = $input.item.json;
// ── v6: force-render gate ────────────────────────────────────
// (a) Prep Records flagged this host as a known page that builds itself in the browser: skip static processing.
// (b) Raw HTML has page that builds itself in the browser framework markers AND no JSON-LD JobPosting: also skip.
// In either case return immediately so Is JS-Rendered? routes to Jina/Decodo.
if (!(prev.ats_platform === 'dayforce' || prev.ats_platform === 'paycom' || prev.ats_platform === 'oracle_ce' || prev.ats_platform === 'adp_cx' || prev.ats_platform === 'applitrack' || prev.ats_platform === 'bamboohr') && (prev.force_render === true || (function(){
  var rawBodyForCheck = (response.body || response.data || '').toString();
  if (rawBodyForCheck.length === 0) return false;
  var hasLdJob = /<script[^>]+application\/ld\+json[^>]*>[^<]*JobPosting/i.test(rawBodyForCheck);
  if (hasLdJob) return false;
  // page that builds itself in the browser framework markers: generic + Phenom-specific.
  var SPA_MARKERS = [
    /__NEXT_DATA__/i,
    /window\.__APOLLO_STATE__/i,
    /data-reactroot/i,
    /id="root"[^>]*>\s*<\/div>/i,
    /id="app"[^>]*>\s*<\/div>/i,
    /position_fields["']?\s*[,:]/i,
    /tabsDisplayConfig/i,
    /shareLinksMetadataConfig/i,
  ];
  return SPA_MARKERS.some(function(rx){ return rx.test(rawBodyForCheck); });
})())) {
  return { json: {
    record_id: prev.record_id,
    job_link: prev.original_job_link || prev.job_link,
    company: prev.company,
    current_address: prev.current_address || '',
    ats_platform: prev.ats_platform || null,
    original_job_link: prev.original_job_link || null,
    fetch_failed: true,
    fail_reason: prev.force_render ? 'force_render host' : 'SPA framework markers in raw HTML, no JSON-LD JobPosting',
    fail_status: 'JS-Rendered (paste into Raw Job Text)'
  } };
}


if (prev.raw_job_text && prev.raw_job_text.trim().length > 200) {
  let text = prev.raw_job_text.trim();
  if (text.length > 8000) text = text.substring(0, 8000);
  return { json: {
    record_id: prev.record_id, job_link: prev.job_link, company: prev.company,
    fetch_failed: false, js_shell_suspected: false, source: 'raw_paste',
    page_text: text, text_length: text.length,
    current_address: prev.current_address || '',
    ats_platform: prev.ats_platform || null,
    original_job_link: prev.original_job_link || null
  }};
}

// ats-json-handler-v9
// If Prep Records rewrote the URL to an ATS API, the response may be JSON.
// Parse and extract job content from known ATS response formats.
if (prev.ats_platform) {
  const atsPlatform = prev.ats_platform;
  const rawBody = response.body || response.data || '';

  function atsCleanHtml(h){ return String(h||'')
    .replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|li|ul|ol|tr|h[1-6])>/gi,'\n')
    .replace(/<li[^>]*>/gi,'\n• ').replace(/<[^>]+>/g,' ')
    .replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>')
    .replace(/&#39;/g,"'").replace(/&rsquo;/g,"'").replace(/&lsquo;/g,"'").replace(/&quot;/g,'"')
    .replace(/&ndash;/g,'–').replace(/&mdash;/g,'—')
    .replace(/[\t ]+/g,' ').replace(/ *\n */g,'\n').replace(/\n{3,}/g,'\n\n').trim(); }

  // -- Dayforce HCM: SSR __NEXT_DATA__ parser (v4) ---------------
  // Prep Records rewrites regional hosts (us241, us252...) to jobs.dayforcehcm.com,
  // which server-side-renders the full posting into __NEXT_DATA__ (no API/auth needed).
  if (atsPlatform === 'dayforce') {
    try {
      var _ndM = rawBody.match(/<script id="__NEXT_DATA__" type="application\/json">([\s\S]*?)<\/script>/);
      if (_ndM) {
        var _nd = JSON.parse(_ndM[1]);
        var _jd = _nd.props && _nd.props.pageProps && _nd.props.pageProps.jobData;
        if (_jd && (_jd.jobTitle || (_jd.jobPostingContent && _jd.jobPostingContent.jobDescription))) {
          var _dfLoc = '';
          (_jd.postingLocations || []).forEach(function(l){
            var a = l.formattedAddress || [l.address, l.cityName, l.stateCode, l.postalCode].filter(Boolean).join(', ');
            if (a) { a = String(a).replace(/,\s*USA?$/i,'').replace(/,\s*United States$/i,''); _dfLoc += '• ' + a + '\n'; }
          });
          var _attrs = _jd.jobPostingAttributes || [];
          function _dfAttr(n){ var f = _attrs.find(function(x){ return x.name === n; }); return f ? f.value : null; }
