    if (bhJob.datePosted) bhHead += 'LISTING DATES: posted ' + bhJob.datePosted + '\n';

    var bhPage = '';
    if (bhHead) bhPage += '=== STRUCTURED DATA (authoritative) ===\n' + bhHead + '\n=== PAGE TEXT ===\n';
    if (bhTitle) bhPage += bhTitle + '\n\n';
    bhPage += bhBody;

    return { json: {
      record_id: prev.record_id, job_link: prev.original_job_link || prev.job_link,
      original_job_link: prev.original_job_link || null,
      ats_platform: prev.ats_platform || null,
      company: prev.company, raw_job_text: prev.raw_job_text || null,
 current_address: prev.current_address || '',
      fetch_failed: false, js_shell_suspected: false, source: 'ats_api_bamboohr',
      page_text: bhPage.slice(0, 25000), text_length: bhPage.length } };
  }
  // ── BAMBOOHR_HANDLER_END ──

  // talentlink-handler-v3: TalentLink/TGS boards (Angular page that builds itself in the browser)
  // Job data lives as HTML-encoded Q&A pairs: QuestionName&quot;:&quot;NAME&quot;,&quot;AnswerValue&quot;:&quot;VALUE&quot;,&quot;VerityZone
  // Using simple indexOf extraction: no regex, no escaping issues.
  if (atsPlatform === 'talentlink') {
    try {
      function tlGet(name) {
        var mk = 'QuestionName&quot;:&quot;' + name + '&quot;,&quot;AnswerValue&quot;:&quot;';
        var em = '&quot;,&quot;VerityZone';
        var i = rawBody.indexOf(mk);
        if (i === -1) return '';
        var s = i + mk.length;
        var e = rawBody.indexOf(em, s);
        return e === -1 ? '' : rawBody.slice(s, e);
      }
      function tlClean(raw) {
        if (!raw) return '';
        // Decode HTML entities
        var s = raw.replace(/&quot;/g, '"').replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'");
        // Decode JSON \uXXXX unicode escapes
        s = s.replace(/\\u([0-9a-fA-F]{4})/g, function(_, h) {
          return String.fromCharCode(parseInt(h, 16));
        });
        // Convert HTML line breaks and tags to plain text
        s = s.replace(/<br\s*\/?>/gi, '\n')
          .replace(/<p[^>]*>/gi, '\n').replace(/<\/p>/gi, '\n')
          .replace(/<li[^>]*>/gi, '\n- ').replace(/<[^>]+>/g, '');
        // Normalise literal \n sequences left in the text
        s = s.replace(/\\n/g, '\n');
        // Collapse excessive blank lines
        s = s.replace(/\n{3,}/g, '\n\n').trim();
        return s;
      }

      var tlSalRaw  = tlGet('Salary information');
      var tlCityRaw = tlGet('City');
      var tlCtStRaw = tlGet('Country / State');
      var tlTitleRaw = tlGet('Title');
      var tlRoleRaw  = tlGet('Your role') || tlGet('Job Description') || tlGet('Description');
      var tlTeamRaw  = tlGet('Your team');
      var tlExpRaw   = tlGet('Your expertise') || tlGet('Qualifications') || tlGet('Requirements');

      if (tlSalRaw || tlCityRaw || tlCtStRaw || tlRoleRaw) {
        // ── Location: build STRUCTURED DATA for rescueAllowedStates ──────
        // Country / State arrives as for example "United States - New Jersey"
        // Always emit State first so the rescue function finds it easily.
        var tlCity   = tlClean(tlCityRaw);
        var tlCtSt   = tlClean(tlCtStRaw);
        var tlCtry   = '';
        var tlStPart = '';
        if (tlCtSt) {
          var tlParts = tlCtSt.split(' - ');
          tlCtry   = tlParts[0] || '';
          tlStPart = tlParts.slice(1).join(', ') || '';
        }
        var tlHiLoc = '';
        if (tlCity || tlStPart) {
          var tlLocParts = [];
          if (tlCity)   tlLocParts.push(tlCity);
          if (tlStPart) tlLocParts.push(tlStPart);
          if (tlCtry)   tlLocParts.push(tlCtry);
          tlHiLoc = '• ' + tlLocParts.join(', ');
        }

        var tlPageText = '';
        if (tlHiLoc) {
          tlPageText += '=== STRUCTURED DATA (authoritative) ===\nHIRING LOCATIONS:\n' + tlHiLoc + '\n\n';
        }

        // ── Salary: emit STRUCTURED SALARY line ───────────────────────────
        var tlSalClean = tlClean(tlSalRaw);
        if (tlSalClean) {
          var tlSalMatch = tlSalClean.match(/min\s+USD\s*([\d,]+)\s*[-\u2013]\s*max\s+USD\s*([\d,]+)\s*\/annum/i);
          if (tlSalMatch) {
            var tlMin = tlSalMatch[1].replace(/,/g, '');
            var tlMax = tlSalMatch[2].replace(/,/g, '');
            tlPageText += 'STRUCTURED SALARY: $' + tlMin + ' - $' + tlMax + ' [ANNUAL]\n';
          }
        }

        // ── Page text body ────────────────────────────────────────────────
        tlPageText += '\n=== PAGE TEXT ===\n';
        if (tlTitleRaw)  tlPageText += tlClean(tlTitleRaw) + '\n\n';
        if (tlRoleRaw)   tlPageText += 'ROLE DESCRIPTION:\n' + tlClean(tlRoleRaw) + '\n\n';
        if (tlTeamRaw)   tlPageText += 'YOUR TEAM:\n' + tlClean(tlTeamRaw) + '\n\n';
        if (tlExpRaw)    tlPageText += 'QUALIFICATIONS:\n' + tlClean(tlExpRaw) + '\n\n';
        if (tlSalClean)  tlPageText += 'SALARY INFORMATION:\n' + tlSalClean + '\n\n';

        return { json: {
          record_id: prev.record_id,
          job_link: prev.job_link,
          original_job_link: prev.original_job_link || null,
          ats_platform: prev.ats_platform || null,
          company: prev.company,
          raw_job_text: prev.raw_job_text || null,
          current_address: prev.current_address || '',
          fetch_failed: false,
          page_text: tlPageText.slice(0, 25000)
        }};
      }
    } catch(tlErr) { /* fall through to JS-Rendered — tlErr silently ignored */ }
  }
  // ATS API failed or returned non-JSON: report as JS-Rendered with ATS name
  // ── v3: Jobvite (?nl=1) and ClearCompany return server-rendered HTML ──
  // Do NOT return JS-Rendered for these platforms; let the code fall through
  // to the standard HTML-strip + JSON-LD parsing section below.
  if (atsPlatform !== 'jobvite' && atsPlatform !== 'clearcompany') {
    const atsLabel = { adp: 'ADP Workforce Now', adp_mascsr: 'ADP Workforce Now (mascsr)', bullhorn: 'Bullhorn OSCP',
      paycom: 'Paycom ATS', textron: 'Textron/Radancy',
      dayforce: 'Dayforce HCM', taleo: 'Oracle Taleo', phenom: 'Phenom People',
      ukg: 'UltiPro / UKG Pro',
      oracle_ce: 'Oracle Recruiting Cloud'
    }[atsPlatform] || atsPlatform;
    return { json: { record_id: prev.record_id, job_link: prev.original_job_link || prev.job_link, company: prev.company,
      fetch_failed: true,
      fail_reason: 'ATS platform requires JavaScript: ' + atsLabel + ' — paste job text into Raw Job Text field',
      fail_status: 'JS-Rendered (paste into Raw Job Text)' }};
  }
  // For jobvite / clearcompany: fall through to standard HTML processing below
}

const statusCode = response.statusCode || response.status;
const body = response.body || response.data || '';

if (statusCode === 404 || statusCode === 410) {
  return { json: { record_id: prev.record_id, job_link: prev.job_link, company: prev.company,
    fetch_failed: true, fail_reason: `Dead posting (${statusCode}) — job likely filled or removed`,
    fail_status: 'Dead Link' }};
}
if (!statusCode || statusCode >= 400) {
  return { json: { record_id: prev.record_id, job_link: prev.job_link, company: prev.company,
    fetch_failed: true, fail_reason: `HTTP ${statusCode} — possibly blocked`,
    fail_status: 'Fetch Error' }};
}
if (!body || body.length < 500) {
  const isAvatureBlocked = /careers\.cbre\.com|avature/i.test(prev.job_link || '') || statusCode === 202;
  return { json: { record_id: prev.record_id, job_link: prev.job_link, company: prev.company,
    fetch_failed: true,
    fail_reason: isAvatureBlocked
      ? `CBRE/Avature returned HTTP ${statusCode || 'unknown'} with body length ${body.length} — bot/WAF challenge, trying reader fallback`
      : `Body length ${body.length} — empty response`,
    fail_status: isAvatureBlocked ? 'JS-Rendered (paste into Raw Job Text)' : 'Empty Response' }};
}

// ── STRUCTURED DATA EXTRACTION ─────────────────────────���───────────────────
// Uses RegExp constructor everywhere: avoids regex-literal escaping issues across environments.
let jsonLdBonus = '';

const SS = '[\\s\\S]';
const scriptLdRx   = new RegExp('<script[^>]+type=["\']application\\/ld\\+json["\'][^>]*>(' + SS + '*?)<\\/script>', 'gi');
const scriptIdRx   = new RegExp('<script[^>]+id=["\']__NEXT_DATA__["\'][^>]*>(' + SS + '*?)<\\/script>', 'i');
const metaSalaryRx = new RegExp('<meta[^>]+(?:name|property)=["\'](?:salary|pay|compensation)[^"\']*["\'][^>]+content=["\']([^"\']+)["\']', 'i');

// 1) Next.js __NEXT_DATA__: find salary/location keys recursively
const nextM = body.match(scriptIdRx);
if (nextM) {
  try {
    const nd = JSON.parse(nextM[1]);
    const WANTED = ['salary','minsalary','maxsalary','basesalary','compensationmin','compensationmax',
      'hourlyrate','annualsalary','paylevel','payrate','city','state','location','locations',
      'addresslocality','addressregion'];
    function pickKeys(obj, depth) {
      if (!obj || typeof obj !== 'object' || depth > 7) return {};
      const out = {};
      for (const k of Object.keys(obj)) {
        const kl = k.toLowerCase();
        if (WANTED.includes(kl) && obj[k] !== null && obj[k] !== '') out[kl] = obj[k];
        Object.assign(out, pickKeys(obj[k], depth + 1));
      }
      return out;
    }
    const found = pickKeys(nd, 0);
    if (Object.keys(found).length > 0) {
      jsonLdBonus += '\nNEXT_DATA: ' + JSON.stringify(found).substring(0, 400) + '\n';
    }
  } catch(e) {}
}

// 2) Meta tag salary
const metaM = body.match(metaSalaryRx);
if (metaM) jsonLdBonus += '\nMETA SALARY: ' + metaM[1] + '\n';

// 3) JSON-LD JobPosting (iCIMS, Greenhouse, Lever, SmartRecruiters, most ATS platforms)
const ldRaw = [];
let ldM;
scriptLdRx.lastIndex = 0;
while ((ldM = scriptLdRx.exec(body)) !== null) ldRaw.push(ldM[1]);

for (const raw of ldRaw) {
  try {
    const data = JSON.parse(raw);
    // Unwrap JSON-LD @graph arrays
    const jldItems = data['@graph'] ? data['@graph'] : (Array.isArray(data) ? data : [data]);
    // If the URL has a jobId query param (for example company.com?jobId=UUID), try to match
    // the specific posting rather than picking the first one (fixes wrapper career pages
    // that embed multiple JobPosting entries: for example ClearCompany-powered sites).
    const jobIdParam = (prev.job_link || '').match(/[?&]jobId=([^&#]+)/i);
    let posting = null;
    if (jobIdParam && jldItems.length > 1) {
      const jidLower = jobIdParam[1].toLowerCase();
      posting = jldItems.find(d => d['@type'] === 'JobPosting' &&
        d.url && d.url.toLowerCase().includes(jidLower));
    }
    if (!posting) posting = jldItems.find(d => d['@type'] === 'JobPosting');
    if (!posting) continue;

    const locs = posting.jobLocation
      ? (Array.isArray(posting.jobLocation) ? posting.jobLocation : [posting.jobLocation])
      : [];
    if (locs.length > 0) {
      jsonLdBonus += '\nHIRING LOCATIONS:\n';
      for (const loc of locs) {
        const a = loc.address || {};
        const parts = [];
        if (a.streetAddress && a.streetAddress !== 'UNAVAILABLE') parts.push(a.streetAddress);
        if (a.addressLocality) parts.push(a.addressLocality);
        if (a.addressRegion) parts.push(a.addressRegion);
        if (a.postalCode && a.postalCode !== 'UNAVAILABLE') parts.push(a.postalCode);
        if (a.addressCountry) parts.push(a.addressCountry);
        if (parts.length > 0) jsonLdBonus += '• ' + parts.join(', ') + '\n';
      }
    }

    if (posting.description) {
      let desc = posting.description
        .replace(new RegExp('<script[^>]*>(' + SS + '*?)<\/script>', 'gi'), ' ')
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
        .replace(/\s+/g, ' ').trim();
      // No character limit on the structured description, it is always relevant content.
      // The LLM (DeepSeek V3, 128k context) easily handles even the longest job postings.
      jsonLdBonus += '\nJOB DESCRIPTION (from structured data):\n' + desc;
    }

    const bs = posting.baseSalary;
    if (bs && bs.value) {
      const v = bs.value;
      const mn = v.minValue || v.value || 0;
      const mx = v.maxValue || v.value || 0;
      if (mn > 0 || mx > 0) {
        // v5: normalise unitText to bracketed [HOURLY]/[ANNUAL] tag
          var _utL = (v.unitText || '').toString().toLowerCase();
          // v7: magnitude guard: a max under $250 cannot be an annual figure (ATS unitText is often wrong or empty)
          var _utUnit = (_utL.indexOf('hour') !== -1 || _utL === 'h') ? 'HOURLY' : ((mx > 0 && mx < 250) ? 'HOURLY' : 'ANNUAL');
          jsonLdBonus += '\n\nSTRUCTURED SALARY: ' + mn + ' - ' + mx + ' [' + _utUnit + ']\n';
      }
    }

    // Salary from description text: handles ATS platforms where baseSalary fields are zeroed out
    if (!jsonLdBonus.includes('STRUCTURED SALARY:') && posting.description) {
      const descPlain = posting.description.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
      const sm = descPlain.match(/[$][\d,]+(?:\.\d+)?[Kk]?\s*[-–—]\s*[$][\d,]+(?:\.\d+)?[Kk]?(?:\s+(?:per\s+(?:hour|year)|hourly|annually))?/i);
      if (sm) {
        // v7: unit from surrounding context (±80 chars) + magnitude, not just the matched string
        const smCtx = descPlain.substring(Math.max(0, sm.index - 80), sm.index + sm[0].length + 40);
        const smNums = (sm[0].match(/[\d,]+(?:\.\d+)?[Kk]?/g) || []).map(function(x){ return parseFloat(x.replace(/,/g, '')) * (/[Kk]$/.test(x) ? 1000 : 1); });
        const smMax = smNums.length ? Math.max.apply(null, smNums) : 0;
        let unit;
        if (/hour|\bhr\b/i.test(smCtx) && !/annual|per\s+year|yearly/i.test(smCtx)) unit = 'HOURLY';
        else if (/annual|per\s+year|yearly/i.test(smCtx)) unit = 'ANNUAL';
        else unit = (smMax > 0 && smMax < 250) ? 'HOURLY' : 'ANNUAL';
        jsonLdBonus += '\nSTRUCTURED SALARY: ' + sm[0].trim() + ' [' + unit + ']\n';
      }
    }
  } catch(e) {}
}

// ── HTML STRIP ─────────────────────────────────────────────────────────────
function stripBlock(tag, b) {
  return b.replace(new RegExp('<' + tag + '[^>]*>(' + SS + '*?)<\/' + tag + '>', 'gi'), ' ');
}

let text = body;
// Strip block-level elements that are always peripheral, never contain the main job posting
for (const tag of ['script','style','nav','footer','header','noscript','svg','aside']) {
  text = stripBlock(tag, text);
}
text = text
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|section|article|main|aside|form|ul|ol|tr|table|h[1-6]|pre|blockquote|figure)>/gi, '\n')
  .replace(/<(p|div|section|article|main|aside|form|ul|ol|tr|table|h[1-6]|pre|blockquote|figure)[^>]*>/gi, '\n')
  .replace(/<\/li>/gi, '\n')
  .replace(/<li[^>]*>/gi, '\n• ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&rsquo;/g, "'").replace(/&lsquo;/g, "'")
  .replace(/&rdquo;/g, '"').replace(/&ldquo;/g, '"').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—')
  .replace(/&bull;/g, '•').replace(/&hellip;/g, '...').replace(/&#x2019;/g, "'").replace(/&#x2013;/g, '–')
  .replace(/[\t ]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ── SIDEBAR / RELATED-JOBS TRIM ────────────────────────────────────────────
// Job pages often embed "Similar Jobs", "You May Also Like", "Related Positions"
// widgets below the main posting. After HTML stripping these appear as plain text
// and confuse the LLM with other job titles, locations, and salaries.
// Strategy: find the first occurrence of a known sidebar heading and cut there.
// We require it to appear after at least 500 chars (skip trivial false positives).
const SIDEBAR_MARKERS = [
  'similar jobs', 'related jobs', 'jobs you may like', 'jobs you might like',
  'more jobs like this', 'other jobs at', 'other open positions',
  'other opportunities', 'you may also like', 'recommended jobs',
  'explore more jobs', 'also hiring', 'related opportunities',
  'other positions at', 'more opportunities', 'jobs near you',
  'people also searched', 'similar openings', 'explore open roles'
];
const textLower = text.toLowerCase();
let sidebarCut = -1;
for (const marker of SIDEBAR_MARKERS) {
  // Match only when the marker appears on its own line (preceded by \n or start)
  const idx = textLower.indexOf('\n' + marker);
  if (idx > 500 && (sidebarCut === -1 || idx < sidebarCut)) {
    sidebarCut = idx;
  }
}
if (sidebarCut > 500) {
  text = text.substring(0, sidebarCut).trim();
}

if (jsonLdBonus.trim()) {
  text = '=== STRUCTURED DATA (authoritative) ===\n' + jsonLdBonus.trim() + '\n\n=== PAGE TEXT ===\n' + text;
}

const pageOnly = text.replace(new RegExp('^' + SS + '*?=== PAGE TEXT ==='), '');
// v5/v6: page that builds itself in the browser-shell detection: require >= 2 job-content keywords.
const JOB_KW_V5 = ['qualif','responsib','salary','compensat','requirement','description','experienc','benefit','position','role','duty','duties','pay rate','hourly','annual','wage','employment'];
const pageOnlyLowerV5 = pageOnly.toLowerCase();
const kwHitsV5 = JOB_KW_V5.filter(function(k){ return pageOnlyLowerV5.indexOf(k) !== -1; }).length;
const hasJobContent = kwHitsV5 >= 2;
if (!jsonLdBonus.trim() && (pageOnly.length < 800 || !hasJobContent)) {
  return { json: { record_id: prev.record_id, job_link: prev.job_link, company: prev.company,
    fetch_failed: true,
    fail_reason: `Stripped text only ${pageOnly.length} chars — JS-rendered SPA`,
    fail_status: 'JS-Rendered (paste into Raw Job Text)' }};
}

// Safety-net cap only: prevents runaway costs from extremely bloated pages (for example SPAs with 500kb of JS artifacts).
// Normal and long job postings (even 10,000+ word descriptions) will be well under this limit.
if (text.length > 25000) text = text.substring(0, 25000);

return { json: {
  record_id: prev.record_id, job_link: prev.job_link, company: prev.company,
  fetch_failed: false, js_shell_suspected: false, source: 'http_fetch',
  page_text: text, text_length: text.length
}};

// ── V55_ADDRESS_START: the address format (2026-08-19) ──
var V55_STATES = {
  ALABAMA:'AL', ALASKA:'AK', ARIZONA:'AZ', ARKANSAS:'AR', CALIFORNIA:'CA', COLORADO:'CO',
  CONNECTICUT:'CT', DELAWARE:'DE', FLORIDA:'FL', GEORGIA:'GA', HAWAII:'HI', IDAHO:'ID',
  ILLINOIS:'IL', INDIANA:'IN', IOWA:'IA', KANSAS:'KS', KENTUCKY:'KY', LOUISIANA:'LA',
  MAINE:'ME', MARYLAND:'MD', MASSACHUSETTS:'MA', MICHIGAN:'MI', MINNESOTA:'MN',
  MISSISSIPPI:'MS', MISSOURI:'MO', MONTANA:'MT', NEBRASKA:'NE', NEVADA:'NV',
  'NEW HAMPSHIRE':'NH', 'NEW JERSEY':'NJ', 'NEW MEXICO':'NM', 'NEW YORK':'NY',
  'NORTH CAROLINA':'NC', 'NORTH DAKOTA':'ND', OHIO:'OH', OKLAHOMA:'OK', OREGON:'OR',
  PENNSYLVANIA:'PA', 'RHODE ISLAND':'RI', 'SOUTH CAROLINA':'SC', 'SOUTH DAKOTA':'SD',
  TENNESSEE:'TN', TEXAS:'TX', UTAH:'UT', VERMONT:'VT', VIRGINIA:'VA',
  WASHINGTON:'WA', 'WEST VIRGINIA':'WV', WISCONSIN:'WI', WYOMING:'WY',
  'DISTRICT OF COLUMBIA':'DC', 'WASHINGTON D.C.':'DC', 'WASHINGTON DC':'DC'
};
var V55_CODES = {};
for (var _k in V55_STATES) V55_CODES[V55_STATES[_k]] = true;

// A country token on its own, or trailing on an address.
var V55_COUNTRY = /^(?:u\.?\s?s\.?(?:a\.?)?|united\s+states(?:\s+of\s+america)?)$/i;

function v55Normalise(raw) {
  if (raw === null || raw === undefined) return null;
  var s = String(raw).trim();
  if (!s) return null;

  // A bare count string is the multi-location marker (PATH 3/5), not an address.
  if (/^\d{1,3}$/.test(s)) return s;

  // 1. drop the appended duplicate zip ("… IL 60188 - 60188", "… NJ 07652 - 07652")
  //    A trailing " - <5 digits>" is never a facility name.
  s = s.replace(/\s*[-–]\s*\d{5}(?:-\d{4})?\s*$/, '').trim();

  // 1b. a REAL trailing facility name ("Sewell, New Jersey - Select Surgical Center
  //     at Kennedy") is kept, but set aside so the state in front of it still gets
  //     its initials. Re-appended word for word at the end.
  //     ⚠️ Fires ONLY when the part before the final " - " ENDS in a spelled-out
  //     state, so a facility PREFIX ("University Park - Los Angeles, CA 90007",
  //     "Seaglass - Willowbrook 3 - Los Angeles, CA") is never mistaken for one.
  var facility = '';
  var _lastDash = s.lastIndexOf(' - ');
  if (_lastDash > 0) {
    var _head = s.slice(0, _lastDash).trim();
    var _tail = s.slice(_lastDash + 3).trim();
    var _hSegs = _head.split(',');
    var _hLast = _hSegs[_hSegs.length - 1].trim().replace(/\s+\d{5}(?:-\d{4})?$/, '');
    if (V55_STATES[_hLast.toUpperCase()] && /[A-Za-z]/.test(_tail)) {
      s = _head; facility = _tail;
    }
  }

  // 2. strip a trailing country, however it is punctuated
  var guard = 0;
  while (guard++ < 4) {
    var before = s;
    s = s.replace(/[,\s]+(?:u\.?\s?s\.?a?\.?|united\s+states(?:\s+of\s+america)?)\s*$/i, '').trim();
    s = s.replace(/[,\s]+$/, '').trim();
    if (s === before) break;
  }

  // 3. nothing but a country -> the marker
  if (!s || V55_COUNTRY.test(s)) return facility ? 'MAIN - ' + facility : 'MAIN';

  // 4. spelled-out state -> initials.
  //    ⚠️ ONLY the state segment. Cities are named after states: "Washington, DC"
  //    and "New York, New York" must not become "WA, DC" / "NY, NY", so the state
  //    is located positionally (last segment, or the one before a trailing ZIP),
  //    never by matching a state name anywhere in the string.
  var parts = s.split(',').map(function (p) { return p.trim(); }).filter(function (p) { return p; });

  // a country can sit mid-string ("Inglewood, California, US, 90301")
  parts = parts.filter(function (p) { return !V55_COUNTRY.test(p); });
  if (!parts.length) return facility ? 'MAIN - ' + facility : 'MAIN';

  var stateIdx = parts.length - 1;
  if (/^\d{5}(?:-\d{4})?$/.test(parts[stateIdx]) && parts.length > 1) stateIdx--;
  var seg = parts[stateIdx];
