// ── NEW v2: Process Jina AI Reader response ─────────────────
// Validates content and reshapes to match Clean HTML then Text output
// so Build Prompt works unchanged.

const prev = $('Loop (rate limit)').item.json;
const failedRecord = $('Is JS-Rendered?').item.json;
const response = $input.item.json;
const body = (response.body || response.data || '').toString().trim();

// Quality gate: >600 chars AND at least one job keyword
