  'requirement','description','experienc','benefit','skill',
  'position','role','duty','duties','pay','hourly','annual'];
const bodyLower = body.toLowerCase();
const hasContent = body.length > 600 && JOB_KW.some(function(k){ return bodyLower.indexOf(k) !== -1; });

if (!hasContent) {
  return { json: {
    record_id: prev.record_id,
    job_link: failedRecord.job_link,
    company: prev.company,
    fetch_failed: true,
    fail_reason: 'Jina AI returned insufficient content (' + body.length + ' chars) — manual paste required',
    fail_status: 'JS-Rendered (paste into Raw Job Text)'
  }};
}


function stripInlineMarkdown(t) {
  if (!t) return '';
  var s = String(t);

  // bold/italic combos, longest marker first
  s = s.replace(/\*\*\*([^\n*]+?)\*\*\*/g, '$1');
  s = s.replace(/___([^\n_]+?)___/g, '$1');
  s = s.replace(/\*\*([^\n*]+?)\*\*/g, '$1');
  s = s.replace(/__([^\n_]+?)__/g, '$1');
  // single-asterisk italics: the markers must sit on word BOUNDARIES, so
  // arithmetic like 2*3*4 and globs like A*STAR are left alone
  s = s.replace(/(^|[\s(\["'])\*(?=\S)([^\n*]+?)(?<=\S)\*(?=$|[\s)\]"'.,;:!?])/g, '$1$2');
  // single-underscore italics: only when the underscores sit on word
  // BOUNDARIES, so snake_case_names are untouched
  s = s.replace(/(^|[\s(\["'])_(?=\S)([^\n_]+?)(?<=\S)_(?=$|[\s)\]"'.,;:!?])/g, '$1$2');
  // inline code
  s = s.replace(/``([^\n]+?)``/g, '$1');
  s = s.replace(/`([^\n`]+?)`/g, '$1');
  // markdown escapes: \* \_ \# ...
  s = s.replace(/\\([\\`*_{}\[\]()#+\-.!])/g, '$1');
  // any leftover ATX marker at line start
  s = s.replace(/^\s*#{1,6}\s+/gm, '');
  return s;
}

function demarkdown(md) {
  if (!md) return '';
