  t = t.replace(/^\s*```[^\n]*\n([\s\S]*?)^\s*```\s*$/gm, '$1');
  // images: drop entirely (alt text is never job content)
  t = t.replace(/!\[[^\]]*\]\([^)]*\)/g, '');
  t = t.replace(/!\[[^\]]*\]\[[^\]]*\]/g, '');
  // links [text](url) -> text   /  [text][ref] -> text  /  bare <url> -> ''
  t = t.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
  t = t.replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1');
  t = t.replace(/<https?:\/\/[^>]*>/gi, '');

  var lines = t.split(/\r?\n/);
  var out = [];
  for (var i = 0; i < lines.length; i++) {
    var L = lines[i];

    // horizontal rules: ---, ***, ___, "* * *"
    if (/^\s*([-*_])(\s*\1){2,}\s*$/.test(L)) { out.push(''); continue; }
    // ATX heading -> plain heading text, blank line around it
    var h = L.match(/^\s*#{1,6}\s+(.*?)\s*#*\s*$/);
    if (h) { out.push(''); out.push(h[1].trim()); out.push(''); continue; }
    // setext underline (=== / ---) under a heading: drop the underline
    if (/^\s*={3,}\s*$/.test(L)) { out.push(''); continue; }
    // blockquote marker
    L = L.replace(/^\s*>+\s?/, '');
    // table row -> cells separated by spaces; drop separator rows
    if (/^\s*\|/.test(L)) {
      if (/^\s*\|[\s:|-]*\|?\s*$/.test(L)) continue;
      L = L.replace(/^\s*\|/, '').replace(/\|\s*$/, '').split('|').map(function (c) { return c.trim(); }).filter(Boolean).join(' — ');
    }
    // list markers -> "• " (keep indentation depth out of it; one bullet level)
    L = L.replace(/^(\s*)[-*+]\s+/, '$1• ');
    L = L.replace(/^(\s*)\d+[.)]\s+/, '$1• ');
    out.push(L);
  }
  t = out.join('\n');

  t = stripInlineMarkdown(t);

  // collapse the blank lines the heading rule introduced
  t = t.replace(/[ \t]+$/gm, '');
  t = t.replace(/\n{3,}/g, '\n\n');
  return t.trim();
}

function pruneLinkChrome(mdText) {
  if (!mdText) return '';
  var lines = String(mdText).split(/\r?\n/);
  var kept = [];
  for (var i = 0; i < lines.length; i++) {
    var L = lines[i];
    var bare = L.trim();
    if (!bare) { kept.push(L); continue; }
    // count markdown links on the line and measure the text left without them
    var links = bare.match(/\[[^\]]*\]\([^)]*\)/g) || [];
    if (links.length) {
      var without = bare.replace(/\[[^\]]*\]\([^)]*\)/g, '').replace(/^[\s•*+\-]+/, '').trim();
      // 2+ links and almost nothing else = navigation row
      if (links.length >= 2 && without.length < 25) continue;
      // a lone link that is the entire line and is short = nav item
      if (links.length === 1 && without.length === 0 && bare.length < 120) continue;
    }
    // image-only line
    if (/^!\[[^\]]*\]\([^)]*\)$/.test(bare)) continue;
    kept.push(L);
  }
  return kept.join('\n');
}

// v27: Jina returns MARKDOWN (X-Return-Format: markdown). Strip its metadata
// header, drop nav/link-soup lines, then convert markdown to clean plain text
// so no "#", "*" or "_" can reach the LLM and be copied into Role Desc.
let text = body
  .replace(/^(Title:|URL Source:|URL:|Markdown Content:|Published Time:|Description:)[^\n]*\n?/gm, '')
  .replace(/^\s*\n/gm, '\n')
  .trim();

text = demarkdown(pruneLinkChrome(text));

// v27: re-gate AFTER cleaning: a page that was only navigation collapses to
// almost nothing here, and should fall through to Decodo rather than be sent
// to the LLM as chrome.
if (text.length < 400) {
  return { json: {
    record_id: prev.record_id,
    job_link: failedRecord.job_link,
    company: prev.company,
    fetch_failed: true,
    fail_reason: 'Jina AI returned navigation/boilerplate only (' + text.length + ' chars after cleaning)',
    fail_status: 'JS-Rendered (paste into Raw Job Text)'
  }};
}

// Sidebar guard: same markers as normal path
const SIDEBAR = [
  'similar jobs','related jobs','jobs you may like','more jobs like this',
  'other jobs at','recommended jobs','explore more jobs','people also searched'
];
const tl = text.toLowerCase();
let cut = -1;
for (let i = 0; i < SIDEBAR.length; i++) {
  const idx = tl.indexOf('\n' + SIDEBAR[i]);
  if (idx > 500 && (cut === -1 || idx < cut)) cut = idx;
}
if (cut > 500) text = text.substring(0, cut).trim();

if (text.length > 25000) text = text.substring(0, 25000);

return { json: {
  record_id: prev.record_id,
  job_link: failedRecord.job_link,
  company: prev.company,
  fetch_failed: false,
  js_shell_suspected: false,
  source: 'jina_ai',
  page_text: text,
  text_length: text.length,
  current_address: prev.current_address || '',
  ats_platform: prev.ats_platform || null,
  original_job_link: prev.original_job_link || null
}};

// Improved Low Pay Scan - v6 ($-anchored + productivity + raise-context aware)
const input = $input.item.json;
const fullText = (input.page_text || '').toString();

if (!fullText || fullText.length < 100) {
  return { json: { ...input, low_pay_prefilter: false, low_pay_reason: 'no_text' } };
}

const text = fullText.toLowerCase();

// Cut off everything after "Featured Jobs" or "Similar Jobs", main pay info is almost always near the top
let mainContent = fullText;
const cutoffMarkers = ['featured jobs', 'similar jobs', 'you may also like', 'related jobs', 'jobs you might like'];
for (const marker of cutoffMarkers) {
  const idx = text.indexOf(marker);
  if (idx > 800) {  // Only cut if it's after the main content
    mainContent = fullText.substring(0, idx);
    break;
  }
}

const mainText = mainContent.toString();

const hourlyPatterns = [
  /\$(\d{1,3}(?:\.\d{1,2})?)\s*\/\s*(?:hr|hour|hourly)/i,
  /\$(\d{1,3}(?:\.\d{1,2})?)\s+per\s+(?:hr|hour)/i,
  /pay[:\s-]*\$?(\d{1,3}(?:\.\d{1,2})?)\s*\/\s*(?:hr|hour)/i
];

const ANNUAL_HINT = /\b(?:annual|yearly|per year|salary|\/yr)\b/i;
const NON_PAY_HINT = /\b(?:differential|bonus|stipend|allowance|incentive|premium|shift pay|sign.?on|hiring bonus|case|cases|piece|pieces|order|orders|selects|pick rate|picks|productivity|standard|quota|throughput|production rate|output|units|cartons|pallets|lines|skus|hours of pto|pto|sick time|accrue|accrual|valued at|benefits valued|per shift|per week|per day|per month|raise|raises|raised|raising|increase|increases|increased|increasing|increment|increments|bump|boost|growth|progression|adjustment|merit|level\s?up|leveling\s?up|promotion|promoted|tier|step\s?up|career path|over\s+\d+\s+(?:months|years|weeks))\b/i;

let detected = null;
let matchedText = null;

for (const rx of hourlyPatterns) {
  const matches = [...mainText.matchAll(new RegExp(rx.source, rx.flags + (rx.flags.includes('g') ? '' : 'g')))];
  for (const m of matches) {
    const n = parseFloat(m[1]);
    if (isNaN(n) || n < 1) continue;

    const contextStart = Math.max(0, m.index - 80);
    const contextEnd = Math.min(mainText.length, m.index + m[0].length + 100);
    const context = mainText.substring(contextStart, contextEnd).toLowerCase();

    if (ANNUAL_HINT.test(context) || NON_PAY_HINT.test(context)) continue;

    // Ceiling/raise detection: "up to $X/hr" near a small number means a raise ceiling, not a wage.
    const before = mainText.substring(Math.max(0, m.index - 60), m.index).toLowerCase();
    if (/(?:up\s+to|earn\s+up\s+to|as\s+much\s+as|maximum\s+of)\s*$/.test(before)) continue;

    // Only flag if it's clearly under $15/hr
    if (n < 15) {
      detected = n;
      matchedText = m[0];
      break;
    }
  }
  if (detected !== null) break;
}

if (detected !== null) {
  return {
    json: {
      ...input,
      low_pay_prefilter: true,
      low_pay_value: detected,
      low_pay_match: matchedText,
      decision_trace: `low_pay_prefilter:hourly=${detected}<15 (in main content)`
    }
  };
}

return { json: { ...input, low_pay_prefilter: false } };

// Process Decodo Web Scraping API response.
// Decodo returns { results: [ { content, status_code... } ] }.
// content is the JS-rendered HTML of the target. We mirror "Clean HTML -> Text"
// output so the rest of the pipeline is unchanged.
const prev = $('Loop (rate limit)').item.json;
const resp = $input.item.json;
const envelope = (resp && resp.body !== undefined) ? resp.body : resp;

function fail(reason, status) {
  return { json: {
    record_id: prev.record_id,
    job_link: prev.original_job_link || prev.job_link,
    company: prev.company,
    fetch_failed: true,
    fail_reason: reason,
    fail_status: status || 'JS-Rendered (paste into Raw Job Text)'
  }};
}

let body = '';
let dStatus = null;
try {
  const results = envelope && envelope.results;
  if (Array.isArray(results) && results.length) {
    body = String(results[0].content || '');
    dStatus = results[0].status_code;
  } else if (typeof envelope === 'string') {
    body = envelope;
  }
} catch (e) {}

if (dStatus === 404 || dStatus === 410) {
  return fail('Decodo: target returned ' + dStatus + ' (posting filled/removed)', 'Dead Link');
}
if (!body || body.length < 500) {
  return fail('Decodo returned body length ' + body.length + ' - still blocked/empty', 'Empty Response');
}

// ---- JSON-LD JobPosting (Avature and most ATS expose this) -----------
let jsonLdBonus = '';
const ldMatches = body.match(/<script[^>]+type=["']application\/ld\+json["'][^>]*>(.*?)<\/script>/gis) || [];
for (const blk of ldMatches) {
  const inner = blk.replace(/<script[^>]*>/i, '').replace(/<\/script>/i, '');
  try {
    const data = JSON.parse(inner);
    const arr = data['@graph'] ? data['@graph'] : (Array.isArray(data) ? data : [data]);
    const posting = arr.find(d => d && d['@type'] === 'JobPosting');
    if (!posting) continue;
    const locs = posting.jobLocation
      ? (Array.isArray(posting.jobLocation) ? posting.jobLocation : [posting.jobLocation]) : [];
    if (locs.length) {
      jsonLdBonus += '\nHIRING LOCATIONS:\n';
      for (const loc of locs) {
        const a = (loc && loc.address) || {};
        const parts = [];
        if (a.streetAddress && a.streetAddress !== 'UNAVAILABLE') parts.push(a.streetAddress);
        if (a.addressLocality) parts.push(a.addressLocality);
        if (a.addressRegion) parts.push(a.addressRegion);
        if (a.postalCode && a.postalCode !== 'UNAVAILABLE') parts.push(a.postalCode);
        if (a.addressCountry) parts.push(typeof a.addressCountry === 'object' ? (a.addressCountry.name || '') : a.addressCountry);
        if (parts.length) jsonLdBonus += '• ' + parts.join(', ') + '\n';
      }
    }
    if (posting.description) {
      const desc = String(posting.description)
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&#39;/g, "'").replace(/&quot;/g, '"')
        .replace(/\s+/g, ' ').trim();
      jsonLdBonus += '\nJOB DESCRIPTION (from structured data):\n' + desc;
    }
    const bs = posting.baseSalary;
    if (bs && bs.value) {
      const v = bs.value;
      const mn = v.minValue || v.value || 0;
      const mx = v.maxValue || v.value || 0;
      if (mn > 0 || mx > 0) jsonLdBonus += '\n\nSTRUCTURED SALARY: ' + mn + ' - ' + mx + ' ' + (v.unitText || '') + '\n';
    }
  } catch (e) {}
}

// ---- Taleo-specific extractor (runs only when ats_platform='taleo') --------
// Taleo Career Section pages are JS-rendered. After Decodo renders, the job text
// sits inside specific div IDs (requisitionDescriptionInterface.IDxxxx.row1) and
// a .titlepage span. Extract directly so we don't lose them in the generic strip.
if (prev.ats_platform === 'taleo') {
  try {
    let taleoTitle = '';
    let taleoDesc = '';
    let taleoQual = '';
    let taleoLoc = '';
    let taleoSalary = '';

    // Title
    const titleM = body.match(/<span[^>]*class="[^"]*titlepage[^"]*"[^>]*>([^<]+)<\/span>/i) ||
                   body.match(/<h1[^>]*>([^<]+)<\/h1>/i);
    if (titleM) taleoTitle = titleM[1].trim();

    // Description block: Taleo uses requisitionDescriptionInterface.IDxxxx for description and qualifications
    const descBlocks = [...body.matchAll(/<span[^>]+id="requisitionDescriptionInterface\.ID(\d+)\.row1"[^>]*>([\s\S]*?)<\/span>/gi)];
    if (descBlocks.length > 0) {
      // First long block is usually description, second is qualifications
      const cleaned = descBlocks.map(b => b[2].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim());
      taleoDesc = cleaned[0] || '';
      taleoQual = cleaned.slice(1).join('\n\n');
    }

    // Location, salary, schedule sit in dt/dd or label cells, pull plain key/value
    const fieldMap = {};
    const fieldM = [...body.matchAll(/<(?:span|label|td)[^>]*>\s*(Primary Location|Job|Schedule|Job Posting|Minimum Salary|Maximum Salary|Organization|Other Locations)\s*:?\s*<\/(?:span|label|td)>[\s\S]{0,80}?<(?:span|td)[^>]*>([^<]+)<\/(?:span|td)>/gi)];
    for (const m of fieldM) fieldMap[m[1]] = m[2].trim();
    if (fieldMap['Primary Location']) taleoLoc = fieldMap['Primary Location'];
    const mn = parseFloat((fieldMap['Minimum Salary'] || '').replace(/[^\d.]/g, '')) || 0;
    const mx = parseFloat((fieldMap['Maximum Salary'] || '').replace(/[^\d.]/g, '')) || 0;
    if (mn > 0 || mx > 0) taleoSalary = '\nSTRUCTURED SALARY: ' + mn + ' - ' + (mx || mn) + ' [ANNUAL]';

    if (taleoTitle || taleoDesc) {
      let taleoText = '';
      if (taleoLoc) taleoText += '=== STRUCTURED DATA (authoritative) ===\nHIRING LOCATIONS:\n• ' + taleoLoc + '\n';
      taleoText += taleoSalary + '\n\n=== PAGE TEXT ===\n';
      if (taleoTitle) taleoText += taleoTitle + '\n\n';
      if (taleoDesc) taleoText += 'DESCRIPTION:\n' + taleoDesc + '\n\n';
      if (taleoQual) taleoText += 'QUALIFICATIONS:\n' + taleoQual + '\n\n';

      if (taleoText.length > 800) {
        return { json: {
          record_id: prev.record_id,
          job_link: prev.original_job_link || prev.job_link,
          company: prev.company,
          fetch_failed: false,
          js_shell_suspected: false,
          source: 'decodo_taleo',
          page_text: taleoText.substring(0, 25000),
          text_length: taleoText.length,
          current_address: prev.current_address || '',
          ats_platform: prev.ats_platform || null,
          original_job_link: prev.original_job_link || null
        }};
      }
    }
  } catch (e) { /* fall through to generic strip */ }
}

// ---- HTML strip -----------------------------------------------------------
let text = body
  .replace(/<script[^>]*>.*?<\/script>/gis, ' ')
  .replace(/<style[^>]*>.*?<\/style>/gis, ' ')
  .replace(/<(nav|footer|header|noscript|svg|aside)[^>]*>.*?<\/\1>/gis, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|section|article|main|aside|form|ul|ol|tr|table|h[1-6]|pre|blockquote|figure)>/gi, '\n')
  .replace(/<(p|div|section|article|main|aside|form|ul|ol|tr|table|h[1-6]|pre|blockquote|figure)[^>]*>/gi, '\n')
  .replace(/<\/li>/gi, '\n')
  .replace(/<li[^>]*>/gi, '\n• ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&rsquo;/g, "'").replace(/&lsquo;/g, "'")
  .replace(/&rdquo;/g, '"').replace(/&ldquo;/g, '"').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—')
  .replace(/[\t ]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ---- Sidebar / related-jobs trim -----------------------------------------
const SIDEBAR = ['similar jobs','related jobs','jobs you may like','more jobs like this',
  'other jobs at','recommended jobs','explore more jobs','people also searched','you may also like'];
const tl = text.toLowerCase();
let cut = -1;
for (const mk of SIDEBAR) { const idx = tl.indexOf('\n' + mk); if (idx > 500 && (cut === -1 || idx < cut)) cut = idx; }
if (cut > 500) text = text.substring(0, cut).trim();

if (jsonLdBonus.trim()) {
  text = '=== STRUCTURED DATA (authoritative) ===\n' + jsonLdBonus.trim() + '\n\n=== PAGE TEXT ===\n' + text;
}

// ---- Quality gate ---------------------------------------------------------
const JOB_KW = ['qualif','responsib','salary','compensat','location','requirement','description',
  'experienc','benefit','skill','position','role','duty','duties','pay','hourly','annual'];
const low = text.toLowerCase();
const pageOnly = jsonLdBonus.trim() ? text.split('=== PAGE TEXT ===').pop() : text;
const ok = (jsonLdBonus.trim().length > 0) || (pageOnly.length > 800 && JOB_KW.some(k => low.indexOf(k) !== -1));
if (!ok) return fail('Decodo content insufficient (' + pageOnly.length + ' chars) - manual paste required');

if (text.length > 25000) text = text.substring(0, 25000);

return { json: {
  record_id: prev.record_id,
  job_link: prev.original_job_link || prev.job_link,
  company: prev.company,
  fetch_failed: false,
  js_shell_suspected: false,
  source: 'decodo',
  page_text: text,
  text_length: text.length,
  current_address: prev.current_address || '',
  ats_platform: prev.ats_platform || null,
  original_job_link: prev.original_job_link || null
}};

// Build the Airtable payload for a non-Qualified outcome.
// Only keys with a real value are emitted; the Airtable node is on
// autoMapInputData, so anything omitted here is left untouched on the record.
// That keeps a re-checked row from being blanked when an extraction comes back empty.
const j = $input.item.json || {};
const out = { id: j.record_id, Status: 'Error' };
function put(field, v) {
  if (v === undefined || v === null) return;
  if (typeof v === 'string' && !v.trim()) return;
  if (typeof v === 'number' && !isFinite(v)) return;
  out[field] = v;
}
put('Role Name', j.role_name);
put('Role Desc', j.role_desc);
put('Role Qual', j.role_qual);
put('Address', j.address);
put('workplaceType', j.workplace_type);
put('Pay Min', j.pay_min);
put('Pay Max', j.pay_max);
put('Minimum Year', j.minimum_year);
put('Job Type', j.job_type);
put('Also Part-time?', j.also_part_time);
put('Seasonal?', j.seasonal);
put('Pay Unit', j.pay_unit);
if (typeof j.multiple_locations === 'boolean') out['Multiple Locations'] = j.multiple_locations;
return { json: out };

// Build the Airtable payload for a non-Qualified outcome.
// Only keys with a real value are emitted; the Airtable node is on
// autoMapInputData, so anything omitted here is left untouched on the record.
// That keeps a re-checked row from being blanked when an extraction comes back empty.
const j = $input.item.json || {};
const out = { id: j.record_id, Status: 'Skip' };
function put(field, v) {
  if (v === undefined || v === null) return;
  if (typeof v === 'string' && !v.trim()) return;
  if (typeof v === 'number' && !isFinite(v)) return;
  out[field] = v;
}
put('Role Name', j.role_name);
put('Role Desc', j.role_desc);
put('Role Qual', j.role_qual);
put('Address', j.address);
put('workplaceType', j.workplace_type);
put('Pay Min', j.pay_min);
put('Pay Max', j.pay_max);
put('Minimum Year', j.minimum_year);
put('Job Type', j.job_type);
put('Also Part-time?', j.also_part_time);
put('Seasonal?', j.seasonal);
put('Pay Unit', j.pay_unit);
if (typeof j.multiple_locations === 'boolean') out['Multiple Locations'] = j.multiple_locations;
// keep the old marker ONLY when there is nothing real to write, that is, the pre-LLM
// low-pay gate, which skips extraction entirely. Never overwrite real quals with it.
if (!out['Role Qual']) out['Role Qual'] = 'Salary Issue';
return { json: out };
